/**
 * Time left until a moment, ticking each second (`design/components/countdown.md`).
 *
 * Generated by `pnpm shells` from `packages/shells/src/members/countdown.ts`, the member's
 * framework-neutral description. Never edit it by hand: change the description and
 * run `pnpm shells`.
 */
import { Component, DestroyRef, ViewEncapsulation, inject, input, output } from '@angular/core'

import {
  MEMBER_PROVIDERS,
  cell,
  countdownClock,
  countdownLeft,
  countdownMoment,
  countdownSpoken,
  derived,
  devWarning,
  followCountdown,
  useMember,
  watchEffect,
} from '@polymorph/angular'
import styles from '@polymorph/recipes/structure/countdown.module.css'

export interface CountdownMessages {
  mark: (label: string, time: string) => string
}

/** Time left until a moment, ticking each second: the inputs it takes, by the React member's prop names. */
export interface CountdownProps {
  /**
   * Says the time left in a polite line at one minute and at ten seconds. Off, nothing is said.
   */
  announce?: boolean
  /**
   * What it counts to, for assistive technology: "Time until you can send a new code".
   */
  label: string
  /**
   * The locale `Intl` writes the digits and the words in; the page's own when absent.
   */
  locale?: string
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  messages?: CountdownMessages
  /**
   * The moment it counts to: an ISO-8601 instant, as RelativeTime reads its value. Not a number
   * of seconds, which would start again on every render. A server's "retry after 30" becomes a
   * moment once, where the app receives it.
   */
  until: string
}

/** Time left until a moment, ticking each second. */
@Component({
  selector: 'pm-countdown',
  encapsulation: ViewEncapsulation.None,
  host: { style: 'display: contents' },
  providers: [...MEMBER_PROVIDERS],
  // prettier-ignore
  template: `@if (e1()) {<span
[attr.class]="e2()"
[attr.data-ended]="e3()"
data-allow-mismatch="attribute"
data-member="countdown"
><time
role="timer"
[attr.aria-label]="e4()"
[attr.datetime]="e5()"
data-allow-mismatch="text,attribute"
><span
[attr.class]="e6()"
aria-hidden="true"
>{{ e7() }}</span>
<span
[attr.class]="e8()"
>{{ e9() }}</span></time>
@if (e10()) {<span
[attr.class]="e11()"
role="status"
>{{ e12() }}</span>}</span>}`,
})
export class Countdown {
  /**
   * Says the time left in a polite line at one minute and at ten seconds. Off, nothing is said.
   */
  readonly announce = input<
    Exclude<CountdownProps['announce'], undefined>,
    CountdownProps['announce']
  >(false, {
    transform: (value: CountdownProps['announce']) => (value === undefined ? false : value),
  })
  /**
   * What it counts to, for assistive technology: "Time until you can send a new code".
   */
  readonly label = input.required<CountdownProps['label']>()
  /**
   * The locale `Intl` writes the digits and the words in; the page's own when absent.
   */
  readonly locale = input<CountdownProps['locale']>(undefined)
  /**
   * Omit for the generic English defaults; localized hosts pass their own.
   */
  readonly messages = input<CountdownProps['messages']>(undefined)
  /**
   * The moment it counts to: an ISO-8601 instant, as RelativeTime reads its value. Not a number
   * of seconds, which would start again on every render. A server's "retry after 30" becomes a
   * moment once, where the app receives it.
   */
  readonly until = input.required<CountdownProps['until']>()
  /**
   * Called once when the moment is reached, and once after mount when it has already passed.
   */
  readonly onEnd = output<void>({ alias: 'end' })
  protected readonly $ = useMember({
    events: ['end'],
    props: {
      announce: () => this.announce(),
      label: () => this.label(),
      locale: () => this.locale(),
      messages: () => this.messages(),
      until: () => this.until(),
    },
  })
  protected readonly $p = this.$.props
  protected readonly reading = cell(() => null as { at: number; left: number } | null)
  protected readonly said = cell(() => null as { at: number; text: string } | null)
  protected readonly ended = cell(() => null as number | null)
  protected readonly moment = derived(() => countdownMoment(this.$p.until))
  protected readonly say = derived(
    () => this.$p.messages ?? { mark: (label: string, time: string) => label + ': ' + time },
  )
  protected readonly time = derived(() => ({
    left:
      this.reading.value !== null && this.reading.value.at === this.moment.value
        ? this.reading.value.left
        : this.moment.value === null
          ? 0
          : countdownLeft(this.moment.value),
  }))
  protected readonly heard = derived(() =>
    this.said.value !== null && this.said.value.at === this.moment.value
      ? this.said.value.text
      : '',
  )
  protected readonly heed = derived(() => (at: number) => (left: number, marked: boolean): void => {
    this.reading.value = { at: at, left: left }
    if (marked && this.$p.announce)
      this.said.value = {
        at: at,
        text: this.say.value.mark(this.$p.label, countdownSpoken(left, this.$p.locale)),
      }
    if (left === 0 && this.ended.value !== at) {
      this.ended.value = at
      this.$.emit(this.onEnd, 'onEnd')
    }
  })
  private release1: (() => void) | undefined

  constructor() {
    inject(DestroyRef).onDestroy(() => this.release1?.())
    watchEffect(
      () => this.moment.value,
      () => this.effect1(),
      true,
    )
    watchEffect(
      () => this.moment.value,
      () => this.effect2(),
      true,
    )
  }

  protected e1() {
    return this.moment.value !== null
  }

  protected e2() {
    if (!(this.moment.value !== null)) return undefined as never
    return styles.countdown
  }

  protected e3() {
    if (!(this.moment.value !== null)) return undefined as never
    return this.time.value.left === 0 ? '' : undefined
  }

  protected e4() {
    if (!(this.moment.value !== null)) return undefined as never
    return this.$p.label
  }

  protected e5() {
    if (!(this.moment.value !== null)) return undefined as never
    return 'PT' + this.time.value.left + 'S'
  }

  protected e6() {
    if (!(this.moment.value !== null)) return undefined as never
    return styles.digits
  }

  protected e7() {
    if (!(this.moment.value !== null)) return undefined as never
    return countdownClock(this.time.value.left, this.$p.locale)
  }

  protected e8() {
    if (!(this.moment.value !== null)) return undefined as never
    return styles.spoken
  }

  protected e9() {
    if (!(this.moment.value !== null)) return undefined as never
    return countdownSpoken(this.time.value.left, this.$p.locale)
  }

  protected e10() {
    if (!(this.moment.value !== null)) return undefined as never
    return this.$p.announce
  }

  protected e11() {
    if (!(this.moment.value !== null)) return undefined as never
    if (!this.$p.announce) return undefined as never
    return styles.spoken
  }

  protected e12() {
    if (!(this.moment.value !== null)) return undefined as never
    if (!this.$p.announce) return undefined as never
    return this.heard.value
  }

  private effect1(): void {
    this.release1?.()
    const ran =
      this.moment.value === null
        ? undefined
        : followCountdown(this.moment.value, this.heed.value(this.moment.value))
    this.release1 = () => {
      ran?.()
    }
  }

  private effect2(): void {
    devWarning(
      this.moment.value === null,
      `Countdown could not read "${this.$p.until}" as a moment — rendering nothing.`,
    )
  }
}
